class Solution:

	def cal(self, n):
		count = 0
		i = 5
		while True:
			if n // i >= 1:
				count = count + n // i
				i = i * 5
			else:
				break
		return count

	def countZeroes(self, n):
		obj = Solution()
		low = 1
		high = n * 5
		ans = 0
		while low <= high:
			mid = low + (high - low) // 2
			temp = obj.cal(mid)
			if temp == n:
				ans = mid
				break
			elif temp > n:
				high = mid - 1
			else:
				low = mid + 1
		if ans == 0:
			return 0
		return 5
